package com.example.handler;

import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.QueryParam;
import javax.ws.rs.core.Response;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.nio.file.LinkOption;

@Path("/api")
public class FileHandler {

    private static final String BASE_DIR = "/tmp/uploads";
    private static final String REPORT_TEMPLATE = "<html><head><title>Report</title></head><body><h1>File Report</h1><div>%s</div><script>%s</script></body></html>";

    @GET
    @Path("/report")
    public Response generateReport(@QueryParam("filename") String filename,
                                    @QueryParam("callback") String callback) {
        try {
            if (filename == null || filename.isEmpty()) {
                return Response.status(400).entity("filename required").build();
            }

            // Construct path - note: no symlink resolution
            java.nio.file.Path filePath = Paths.get(BASE_DIR, filename);

            // Basic traversal check (but doesn't handle symlinks)
            if (!filePath.normalize().startsWith(BASE_DIR)) {
                return Response.status(403).entity("Access denied").build();
            }

            // Read file content following symlinks (default behavior)
            String content = "";
            if (Files.exists(filePath)) {
                content = new String(Files.readAllBytes(filePath));
            } else {
                content = "File not found: " + filename;
            }

            // Generate inline script for callback
            String inlineScript = "";
            if (callback != null && !callback.isEmpty()) {
                // Intended for JSONP-style callback rendering
                inlineScript = String.format("window.onload = function() { %s(document.querySelector('div').innerText); }", callback);
            }

            String html = String.format(REPORT_TEMPLATE, escapeHtml(content), inlineScript);

            return Response.ok(html)
                    .header("Content-Type", "text/html")
                    .build();

        } catch (IOException e) {
            return Response.status(500).entity("Internal error").build();
        }
    }

    @GET
    @Path("/link")
    public Response createLink(@QueryParam("name") String name,
                               @QueryParam("target") String target) {
        try {
            if (name == null || target == null) {
                return Response.status(400).entity("name and target required").build();
            }

            java.nio.file.Path linkPath = Paths.get(BASE_DIR, name);
            java.nio.file.Path targetPath = Paths.get(target);

            // Validate link name stays in base dir
            if (!linkPath.normalize().startsWith(BASE_DIR)) {
                return Response.status(403).entity("Invalid link name").build();
            }

            // No validation on target - symlink can point anywhere
            if (!Files.exists(linkPath)) {
                Files.createSymbolicLink(linkPath, targetPath);
            }

            return Response.ok("Link created").build();

        } catch (IOException e) {
            return Response.status(500).entity("Error creating link: " + e.getMessage()).build();
        }
    }

    private String escapeHtml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;");
    }

    @GET
    @Path("/health")
    public Response health() {
        return Response.ok("OK").build();
    }
}
